import{_ as r,a0 as l,w as d,s as p,ao as e,I as n,x as a,a1 as i,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 下使用iostat命令生成CPU和I/O的统计报告 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下使用iostat命令生成CPU和I/O的统计报告 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下使用iostat命令生成CPU和I/O的统计报告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下使用iostat命令生成CPU和I/O的统计报告 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Linux iostat Command to Report CPU Statistics and IO Statistics","title":"Linux 下使用iostat命令生成CPU和I/O的统计报告","tag":"201402","desc":""},"relativePath":"201402/Linux iostat Command to Report CPU Statistics and IO Statistics.md","filePath":"[post].md"}'),h={name:"201402/Linux iostat Command to Report CPU Statistics and IO Statistics.md"};function m(g,t,u,c,x,b){const o=l("Link");return d(),p("div",null,[t[14]||(t[14]=e(`<h1 id="linux-下使用iostat命令生成cpu和i-o的统计报告" tabindex="-1">Linux 下使用iostat命令生成CPU和I/O的统计报告 <a class="header-anchor" href="#linux-下使用iostat命令生成cpu和i-o的统计报告" aria-label="Permalink to “Linux 下使用iostat命令生成CPU和I/O的统计报告”">​</a></h1><p>CPU是一台电脑的大脑。所有的处理命令都运行在上面。I/O（输入/输出）同样扮演了一个重要角色。硬盘用于提供数据给处理器并保存CPU处理过的数据。一种衡量处理器和I/O利用率的方法是使用<strong>iostat</strong>命令。通过它们的利用率，我们可以决定是否该增加更多资源。</p><h2 id="iostat-是什么" tabindex="-1">iostat 是什么 <a class="header-anchor" href="#iostat-是什么" aria-label="Permalink to “iostat 是什么”">​</a></h2><p>iostat通过观察设备的活跃时间和他们平均传输率之间的关系来监视系统的输入/输出设备负载。iostat生成的报告可以用于修改系统配置从而更好在物理硬盘间平衡输入/输出的报告。</p><h3 id="安装-iostat" tabindex="-1">安装 iostat <a class="header-anchor" href="#安装-iostat" aria-label="Permalink to “安装 iostat”">​</a></h3><p>iostat包含在<strong>sysstat</strong>包内。如果你没有，你首先需要安装它。</p><h4 id="在-redhat-centos-fedora" tabindex="-1">在 RedHat / CentOS / Fedora <a class="header-anchor" href="#在-redhat-centos-fedora" aria-label="Permalink to “在 RedHat / CentOS / Fedora”">​</a></h4><pre><code># yum install sysstat
</code></pre><h4 id="在-debian-ubuntu-linux-mint" tabindex="-1">在 Debian / Ubuntu / Linux Mint <a class="header-anchor" href="#在-debian-ubuntu-linux-mint" aria-label="Permalink to “在 Debian / Ubuntu / Linux Mint”">​</a></h4><pre><code>$ sudo apt-get install sysstat
</code></pre><h3 id="如何运行-iostat" tabindex="-1">如何运行 iostat <a class="header-anchor" href="#如何运行-iostat" aria-label="Permalink to “如何运行 iostat”">​</a></h3><p>要运行它，只需在控制台下<strong>输入iostat</strong>。下面是一个例子。</p><pre><code>$ iostat
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_default.png" alt="iostat 默认报告"></p><h2 id="下面是如何读取iostat默认报告" tabindex="-1">下面是如何读取iostat默认报告 <a class="header-anchor" href="#下面是如何读取iostat默认报告" aria-label="Permalink to “下面是如何读取iostat默认报告”">​</a></h2><h3 id="第一部分包含了cpu报告" tabindex="-1">第一部分包含了CPU报告 <a class="header-anchor" href="#第一部分包含了cpu报告" aria-label="Permalink to “第一部分包含了CPU报告”">​</a></h3><ul><li><strong>%user</strong> : 显示了在执行用户(应用)层时的CPU利用率</li><li><strong>%nice</strong> : 显示了在以nice优先级运行用户层的CPU利用率</li><li><strong>%system</strong> : 显示了在执行系统(内核)层时的CPU利用率</li><li><strong>%iowait</strong> : 显示了CPU在I/O请求挂起时空闲时间的百分比</li><li><strong>%steal</strong> : 显示了当hypervisor正服务于另外一个虚拟处理器时无意识地等待虚拟CPU所占有的时间百分比。</li><li><strong>%idle</strong> : 显示了CPU在I/O没有挂起请求时空闲时间的百分比</li></ul><h3 id="第二部分包含了设备利用率报告" tabindex="-1">第二部分包含了设备利用率报告 <a class="header-anchor" href="#第二部分包含了设备利用率报告" aria-label="Permalink to “第二部分包含了设备利用率报告”">​</a></h3><ul><li><strong>Device</strong> : 列出的<strong>/dev</strong> 目录下的设备/分区名称</li><li><strong>tps</strong> : 显示每秒传输给设备的数量。更高的tps意味着处理器更忙。</li><li><strong>Blk_read/s</strong> : 显示了每秒从设备上读取的块的数量(KB,MB)</li><li><strong>Blk_wrtn/s</strong> : 显示了每秒写入设备上块的数量(KB,MB)</li><li><strong>Blk_read</strong> : 显示所有已读取的块</li><li><strong>Blk_wrtn</strong> : 显示所有已写入的块</li></ul><h3 id="以kb或mb捕捉iostat" tabindex="-1">以KB或MB捕捉iostat <a class="header-anchor" href="#以kb或mb捕捉iostat" aria-label="Permalink to “以KB或MB捕捉iostat”">​</a></h3><p>默认上，iostat以B为单位衡量I/O系统。为了更便于阅读，我们可以iostat将报告转换成以KB或者MB为单位。只需要加入<strong>-k参数</strong>来创建以<strong>KB为单位</strong>，<strong>-m参数</strong>来创建以<strong>MB为单位</strong>。</p><pre><code>$ iostat -k
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_k.png" alt="以KB为单位的iostat"></p><pre><code>$ iostat -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_m.png" alt="以MB为单位的iostat"></p><p>要扩展报告，我们可以在iostat后面跟上<strong>-x选项</strong>。</p><pre><code>$ iostat -x
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_x.png" alt="扩展iostat报告"></p><h3 id="带延迟使用iostat" tabindex="-1">带延迟使用iostat <a class="header-anchor" href="#带延迟使用iostat" aria-label="Permalink to “带延迟使用iostat”">​</a></h3>`,29)),n("p",null,[t[1]||(t[1]=a("和",-1)),i(o,{href:"http://linoxide.com/linux-command/linux-vmstat-command-tool-report-virtual-memory-statistics/"},{default:s(()=>[...t[0]||(t[0]=[a("vmstat",-1)])]),_:1}),t[2]||(t[2]=a("一样,作为一个统计工具，最好带延迟参数来使用它。通过延迟参数，我们可以看到趋势。这里有一些带延时运行iostat的示例。",-1))]),t[15]||(t[15]=e(`<h3 id="以kb为单位-2秒间隔-运行3次的方式运行iostat" tabindex="-1">以KB为单位，2秒间隔，运行3次的方式运行iostat <a class="header-anchor" href="#以kb为单位-2秒间隔-运行3次的方式运行iostat" aria-label="Permalink to “以KB为单位，2秒间隔，运行3次的方式运行iostat”">​</a></h3><pre><code>$ iostat -k 2 3
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_k_2_3.png" alt="iostat以KB来报告"></p><h3 id="只显示cpu报告-并以3秒为间隔-报告6次" tabindex="-1">只显示CPU报告，并以3秒为间隔，报告6次 <a class="header-anchor" href="#只显示cpu报告-并以3秒为间隔-报告6次" aria-label="Permalink to “只显示CPU报告，并以3秒为间隔，报告6次”">​</a></h3><pre><code>$ iostat -c 3 6
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_c_3_6.png" alt="以3秒为间隔，只显示iostat"></p><h3 id="显示hda2和hda6的设备报告-以2秒为间隔-报告4次" tabindex="-1">显示hda2和hda6的设备报告，以2秒为间隔，报告4次 <a class="header-anchor" href="#显示hda2和hda6的设备报告-以2秒为间隔-报告4次" aria-label="Permalink to “显示hda2和hda6的设备报告，以2秒为间隔，报告4次”">​</a></h3><pre><code>$ iostat -d hda2 hda6 2 4
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/iostat_d_hda2_hda6_2_4.png" alt="只显示硬盘的iostat"></p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><p>iostat使用这些文件来创建报告。</p><p><strong>/proc/stat</strong> 包含了系统统计 <strong>/proc/partitions</strong> 包含磁盘统计 (对于已打过补丁的2.5以前的内核) <strong>/proc/diskstats</strong> 包含磁盘统计 (对于2.5以后的内核) <strong>/sys</strong> 包含块设备统计 (2.5以后内核)</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>vmstat用于监视内存使用，iostat用于监视CPU使用率和I/O系统，这样我们就有了完整的工具来监视你机器中三个重要的组件。这些工具的一个好处是你无需使用root权限运行它们。你可以浏览iostat的手册来深入了解。只需在控制台下输入<strong>man iostat</strong>就可进入iostat手册界面。</p><hr>`,15)),n("p",null,[t[4]||(t[4]=a("via: ",-1)),i(o,{href:"http://linoxide.com/linux-command/linux-iostat-command/"},{default:s(()=>[...t[3]||(t[3]=[a("http://linoxide.com/linux-command/linux-iostat-command/",-1)])]),_:1})]),n("p",null,[t[7]||(t[7]=a("译者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:s(()=>[...t[5]||(t[5]=[a("geekpi",-1)])]),_:1}),t[8]||(t[8]=a(" 校对：",-1)),i(o,{href:"http://blog.csdn.net/tinyeyeser"},{default:s(()=>[...t[6]||(t[6]=[a("Mr小眼儿",-1)])]),_:1})]),n("p",null,[t[11]||(t[11]=a("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[9]||(t[9]=[a("LCTT",-1)])]),_:1}),t[12]||(t[12]=a(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:s(()=>[...t[10]||(t[10]=[a("Linux中国",-1)])]),_:1}),t[13]||(t[13]=a(" 荣誉推出",-1))])])}const _=r(h,[["render",m]]);export{f as __pageData,_ as default};
